{"command":"mkdir -p /tmp/exp && cd /tmp/exp && cat > go.mod <<'EOF'
module exp

go 1.21
EOF
cat > main.go <<'EOF'
package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/printer"
	"go/token"
	"os"
	"sort"
	"strings"
)

func main() {
	src, _ := os.ReadFile(os.Args[1])
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, os.Args[1], src, parser.ParseComments)
	if err != nil {
		panic(err)
	}
	// collect imports and comments
	comments := map[string]string{}
	var paths []string
	type rng struct{ s, e token.Pos }
	var ranges []rng
	for _, d := range f.Decls {
		gd, ok := d.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		for _, s := range gd.Specs {
			is := s.(*ast.ImportSpec)
			p := is.Path.Value
			if p == `"C"` {
				continue
			}
			key := p
			if is.Name != nil {
				key = is.Name.Name + " " + p
			}
			if is.Comment != nil {
				comments[key] = "// " + strings.ReplaceAll(is.Comment.Text(), "\n", "")
			}
			paths = append(paths, key)
		}
	}
	sort.Strings(paths)
	first := true
	for _, d := range f.Decls {
		gd, ok := d.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		isC := false
		for _, s := range gd.Specs {
			if s.(*ast.ImportSpec).Path.Value == `"C"` {
				isC = true
			}
		}
		if isC {
			continue
		}
		ranges = append(ranges, rng{gd.Pos(), gd.End()})
		if first {
			first = false
			var specs []ast.Spec
			for _, p := range paths {
				v := p
				if c, ok := comments[p]; ok {
					v = v + " " + c
				}
				specs = append(specs, &ast.ImportSpec{Path: &ast.BasicLit{Kind: token.STRING, Value: v}})
			}
			gd.Specs = specs
		} else {
			gd.Specs = nil
		}
	}
	// clear comments in ranges
	var kept []*ast.CommentGroup
	for _, c := range f.Comments {
		in := false
		for _, r := range ranges {
			if c.Pos() >= r.s && c.End() <= r.e {
				in = true
			}
		}
		if !in {
			kept = append(kept, c)
		}
	}
	f.Comments = kept
	// remove empty import decls
	var decls []ast.Decl
	for _, d := range f.Decls {
		gd, ok := d.(*ast.GenDecl)
		if ok && gd.Tok == token.IMPORT && len(gd.Specs) == 0 {
			continue
		}
		decls = append(decls, d)
	}
	f.Decls = decls
	var buf bytes.Buffer
	if err := printer.Fprint(&buf, fset, f); err != nil {
		panic(err)
	}
	fmt.Fprintf(os.Stderr, "---- raw ----\n%s\n---- fmt ----\n", strings.ReplaceAll(buf.String(), "\t", "<T>"))
	out, err := format.Source(buf.Bytes())
	if err != nil {
		fmt.Fprintln(os.Stderr, "format err:", err)
		os.Stdout.Write(buf.Bytes())
		return
	}
	os.Stdout.Write(out)
}
EOF
