package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/printer"
	"go/token"
	"os"
)

func main() {
	src, _ := os.ReadFile(os.Args[1])
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "x.go", src, parser.ParseComments)
	if err != nil {
		panic(err)
	}
	tf := fset.File(f.Pos())
	mode := os.Args[2]
	for i := 1; i < len(f.Decls); i++ {
		prev := f.Decls[i-1]
		cur := f.Decls[i]
		start := cur.Pos()
		switch d := cur.(type) {
		case *ast.GenDecl:
			if d.Doc != nil {
				start = d.Doc.Pos()
			}
		case *ast.FuncDecl:
			if d.Doc != nil {
				start = d.Doc.Pos()
			}
		}
		prevEndLine := fset.Position(prev.End()).Line
		curLine := fset.Position(start).Line
		if curLine-prevEndLine < 2 {
			switch mode {
			case "addline-start":
				off := fset.Position(start).Offset
				ok := tf.AddLine(off)
				fmt.Fprintf(os.Stderr, "AddLine(%d)=%v (prevEnd %d cur %d)\n", off, ok, prevEndLine, curLine)
			case "addline-nl":
				off := fset.Position(start).Offset - 1
				ok := tf.AddLine(off)
				fmt.Fprintf(os.Stderr, "AddLine(%d)=%v (prevEnd %d cur %d)\n", off, ok, prevEndLine, curLine)
			case "addline-prevend":
				off := fset.Position(prev.End()).Offset
				ok := tf.AddLine(off)
				fmt.Fprintf(os.Stderr, "AddLine(%d)=%v (prevEnd %d cur %d)\n", off, ok, prevEndLine, curLine)
			}
		}
	}
	var buf bytes.Buffer
	printer.Fprint(&buf, fset, f)
	out, err := format.Source(buf.Bytes())
	if err != nil {
		fmt.Println("ERR", err)
		os.Stdout.Write(buf.Bytes())
		return
	}
	os.Stdout.Write(out)
}
EOF
