package reviser

// SourceFileOption configures the behaviour of SourceFile.Fix.
type SourceFileOption func(f *SourceFile) error

// WithRemovingUnusedImports enables removal of unused imports.
func WithRemovingUnusedImports(f *SourceFile) error {
	f.shouldRemoveUnusedImports = true
	return nil
}

// WithUsingAliasForVersionSuffix enables setting an alias for packages whose
// real name differs from the last element of the import path.
func WithUsingAliasForVersionSuffix(f *SourceFile) error {
	f.shouldUseAliasForVersionSuffix = true
	return nil
}

// WithCodeFormatting enables additional formatting of the declarations.
func WithCodeFormatting(f *SourceFile) error {
	f.shouldFormatCode = true
	return nil
}

// WithSkipGeneratedFile makes generated files untouched.
func WithSkipGeneratedFile(f *SourceFile) error {
	f.shouldSkipAutoGenerated = true
	return nil
}

// WithSeparatedNamedImports separates named imports from the rest in a group.
func WithSeparatedNamedImports(f *SourceFile) error {
	f.shouldSeparateNamedImports = true
	return nil
}

// WithCompanyPackagePrefixes sets the comma-separated list of company prefixes.
func WithCompanyPackagePrefixes(prefixes string) SourceFileOption {
	return func(f *SourceFile) error {
		f.companyPackagePrefixes = splitAndTrim(prefixes)
		return nil
	}
}

// WithImportsOrder sets the order of the import groups.
func WithImportsOrder(order []ImportsOrder) SourceFileOption {
	return func(f *SourceFile) error {
		f.importsOrders = order
		return nil
	}
}
EOF
cat > reviser/order.go <<'EOF'
package reviser

import (
	"errors"
	"fmt"
	"strings"
)

// ImportsOrder is a name of an import group.
type ImportsOrder string

const (
	StdImportsOrder     ImportsOrder = "std"
	CompanyImportsOrder ImportsOrder = "company"
	ProjectImportsOrder ImportsOrder = "project"
	GeneralImportsOrder ImportsOrder = "general"
	BlankedImportsOrder ImportsOrder = "blanked"
	DottedImportsOrder  ImportsOrder = "dotted"
)

const defaultImportsOrder = "std,general,company,project"

// ImportsOrders is a list of import groups in the order they should be rendered.
type ImportsOrders []ImportsOrder

func defaultImportsOrders() ImportsOrders {
	return ImportsOrders{StdImportsOrder, GeneralImportsOrder, CompanyImportsOrder, ProjectImportsOrder}
}

// StringToImportsOrders parses the comma-separated order list.
func StringToImportsOrders(s string) (ImportsOrders, error) {
	if strings.TrimSpace(s) == "" {
		return defaultImportsOrders(), nil
	}

	groups := splitAndTrim(s)
	required := map[ImportsOrder]struct{}{}
	result := make(ImportsOrders, 0, len(groups))
	for _, g := range groups {
		o := ImportsOrder(g)
		switch o {
		case StdImportsOrder, GeneralImportsOrder, CompanyImportsOrder, ProjectImportsOrder:
			required[o] = struct{}{}
		case BlankedImportsOrder, DottedImportsOrder:
		default:
			return nil, fmt.Errorf("unknown order group type: %q", g)
		}
		result = append(result, o)
	}

	if len(required) != 4 {
		return nil, errors.New(`use default at least 4 parameters to sort groups of your imports: "` + defaultImportsOrder + `"`)
	}

	return result, nil
}

func splitAndTrim(s string) []string {
	parts := strings.Split(s, ",")
	result := make([]string, 0, len(parts))
	for _, p := range parts {
		result = append(result, strings.TrimSpace(p))
	}
