package reviser

import (
	"errors"
	"fmt"
	"strings"
)

// ImportsOrder is a name of an import group.
type ImportsOrder string

const (
	StdImportsOrder     ImportsOrder = "std"
	CompanyImportsOrder ImportsOrder = "company"
	ProjectImportsOrder ImportsOrder = "project"
	GeneralImportsOrder ImportsOrder = "general"
	BlankedImportsOrder ImportsOrder = "blanked"
	DottedImportsOrder  ImportsOrder = "dotted"
)

const defaultImportsOrder = "std,general,company,project"

// ImportsOrders is a list of import groups in the order they should be rendered.
type ImportsOrders []ImportsOrder

func defaultImportsOrders() ImportsOrders {
	return ImportsOrders{StdImportsOrder, GeneralImportsOrder, CompanyImportsOrder, ProjectImportsOrder}
}

// StringToImportsOrders parses the comma-separated order list.
func StringToImportsOrders(s string) (ImportsOrders, error) {
	if strings.TrimSpace(s) == "" {
		return defaultImportsOrders(), nil
	}

	groups := splitAndTrim(s)
	required := map[ImportsOrder]struct{}{}
	result := make(ImportsOrders, 0, len(groups))
	for _, g := range groups {
		o := ImportsOrder(g)
		switch o {
		case StdImportsOrder, GeneralImportsOrder, CompanyImportsOrder, ProjectImportsOrder:
			required[o] = struct{}{}
		case BlankedImportsOrder, DottedImportsOrder:
		default:
			return nil, fmt.Errorf("unknown order group type: %q", g)
		}
		result = append(result, o)
	}

	if len(required) != 4 {
		return nil, errors.New(`use default at least 4 parameters to sort groups of your imports: "` + defaultImportsOrder + `"`)
	}

	return result, nil
}

func splitAndTrim(s string) []string {
	parts := strings.Split(s, ",")
	result := make([]string, 0, len(parts))
	for _, p := range parts {
		result = append(result, strings.TrimSpace(p))
	}
	return result
}
EOF
