		if err := opt(f); err != nil {
			return nil, false, err
		}
	}
	if len(f.importsOrders) == 0 {
		f.importsOrders = defaultImportsOrders()
	}

	original, err := os.ReadFile(f.filePath)
	if err != nil {
		return nil, false, err
	}

	fset := token.NewFileSet()
	pf, err := parser.ParseFile(fset, f.filePath, original, parser.ParseComments)
	if err != nil {
		if len(original) == 0 {
			return nil, false, fmt.Errorf("file is empty and cannot be parsed as Go source, use -excludes flag to skip this file: %w", err)
		}
		return nil, false, fmt.Errorf("file has invalid Go source content, use -excludes flag to skip this file: %w", err)
	}

	if f.shouldSkipAutoGenerated && isGeneratedFile(pf) {
		return original, false, nil
	}

	imports, err := f.parseImports(pf)
	if err != nil {
		return nil, false, err
	}

	groups := f.groupImports(imports)

	decls, changedDecls := mergeImportDecls(pf)
	if changedDecls {
		pf.Decls = decls
	}

	f.fixImports(pf, groups, imports)

	if f.shouldFormatCode {
		formatDecls(pf)
	}

	var buf bytes.Buffer
	if err := printer.Fprint(&buf, fset, pf); err != nil {
		return nil, false, err
	}

	formatted, err := format.Source(buf.Bytes())
	if err != nil {
		return nil, false, err
	}

	return formatted, !bytes.Equal(original, formatted), nil
}

// isGeneratedFile reports whether one of the comments before the package
// clause marks the file as generated.
func isGeneratedFile(pf *ast.File) bool {
	for _, group := range pf.Comments {
		if group.Pos() > pf.Package {
			break
		}
		for _, c := range group.List {
			if generatedFileRegexp.MatchString(c.Text) {
				return true
			}
		}
	}
	return false
}

// isCgoDecl reports whether the declaration is a stand-alone import "C".
func isCgoDecl(dd *ast.GenDecl) bool {
	if len(dd.Specs) != 1 {
		return false
	}
	spec, ok := dd.Specs[0].(*ast.ImportSpec)
	return ok && spec.Path.Value == cgoImportPath
}

// parseImports collects all imports (as they are rendered) with their
// trailing comments.
func (f *SourceFile) parseImports(pf *ast.File) (map[string]*importMeta, error) {
	result := map[string]*importMeta{}

	var usage *importsUsage
	if f.shouldRemoveUnusedImports || f.shouldUseAliasForVersionSuffix {
		var err error
		usage, err = loadImportsUsage(filepath.Dir(f.filePath), pf)
		if err != nil {
			return nil, err
		}
	}

	removeUnused := f.shouldRemoveUnusedImports && !hasBlankOrDotImport(pf)

	for _, decl := range pf.Decls {
		dd, ok := decl.(*ast.GenDecl)
		if !ok || dd.Tok != token.IMPORT {
			continue
		}
		if isCgoDecl(dd) {
			continue
		}

		for _, spec := range dd.Specs {
			importSpec, ok := spec.(*ast.ImportSpec)
			if !ok {
				continue
			}

			path := strings.Trim(importSpec.Path.Value, `"`)
			var name string
			if importSpec.Name != nil {
				name = importSpec.Name.Name
			}

			if removeUnused && path != "C" && !usage.isUsed(pf, name, path) {
				continue
			}

			if f.shouldUseAliasForVersionSuffix && name == "" && path != "C" {
				if pkgName, ok := usage.packageName(path); ok && pkgName != filepath.Base(path) {
					name = pkgName
				}
			}

			key := importSpec.Path.Value
			if name != "" {
				key = name + " " + importSpec.Path.Value
			}

			result[key] = &importMeta{comment: importSpec.Comment}
		}
	}

	return result, nil
}

func hasBlankOrDotImport(pf *ast.File) bool {
	for _, imp := range pf.Imports {
		if imp.Name != nil && (imp.Name.Name == "_" || imp.Name.Name == ".") {
			return true
		}
	}
	return false
}

// importGroups holds the imports split by their groups.
type importGroups struct {
	std     []string
	general []string
	company []string
	project []string
	blanked []string
	dotted  []string
}

func (f *SourceFile) groupImports(imports map[string]*importMeta) *importGroups {
	groups := &importGroups{}

	withBlanked := false
	withDotted := false
	for _, o := range f.importsOrders {
		switch o {
		case BlankedImportsOrder:
			withBlanked = true
		case DottedImportsOrder:
			withDotted = true
		}
	}

	for imprt := range imports {
		name, path := splitImport(imprt)
		pkg := strings.Trim(path, `"`)

		if withBlanked && name == "_" {
			groups.blanked = append(groups.blanked, imprt)
			continue
		}
		if withDotted && name == "." {
			groups.dotted = append(groups.dotted, imprt)
			continue
		}

		if _, ok := stdPackages[pkg]; ok {
			groups.std = append(groups.std, imprt)
			continue
		}

		if f.isProjectImport(pkg) {
			groups.project = append(groups.project, imprt)
			continue
		}

		if f.isCompanyImport(pkg) {
			groups.company = append(groups.company, imprt)
			continue
		}

		groups.general = append(groups.general, imprt)
	}

	sortImports(groups.std)
	sortImports(groups.general)
	sortImports(groups.company)
	sortImports(groups.project)
	sortImports(groups.blanked)
	sortImports(groups.dotted)

	return groups
}

func (f *SourceFile) isProjectImport(pkg string) bool {
	return pkg == f.projectName || strings.HasPrefix(pkg, f.projectName+"/")
}

func (f *SourceFile) isCompanyImport(pkg string) bool {
	for _, prefix := range f.companyPackagePrefixes {
		if strings.HasPrefix(pkg, prefix) {
			return true
		}
	}
	return false
}

// splitImport splits the rendered import ("name path" or "path") into its parts.
func splitImport(imprt string) (name, path string) {
	idx := strings.IndexByte(imprt, ' ')
	if idx < 0 {
		return "", imprt
	}
	return imprt[:idx], imprt[idx+1:]
}

func sortImports(imports []string) {
	sort.Slice(imports, func(i, j int) bool {
		ni, pi := splitImport(imports[i])
		nj, pj := splitImport(imports[j])
		if pi != pj {
			return pi < pj
		}
		return ni < nj
	})
}

// mergeImportDecls merges all import declarations (except the stand-alone
// cgo ones) into the first one.
func mergeImportDecls(pf *ast.File) ([]ast.Decl, bool) {
	var (
		merged  bool
		defined bool
	)

	decls := make([]ast.Decl, 0, len(pf.Decls))
	for _, decl := range pf.Decls {
		dd, ok := decl.(*ast.GenDecl)
		if !ok || dd.Tok != token.IMPORT || isCgoDecl(dd) {
			decls = append(decls, decl)
			continue
		}

		if defined {
			merged = true
			if last, ok := decls[len(decls)-1].(*ast.GenDecl); ok && last.Tok == token.IMPORT {
				last.Rparen = dd.End()
			}
			continue
		}

		defined = true
		decls = append(decls, dd)
	}

	return decls, merged
}

type importRange struct {
	start token.Pos
	end   token.Pos
}

func (r importRange) contains(pos token.Pos) bool {
	return pos >= r.start && pos <= r.end
}

func (f *SourceFile) fixImports(pf *ast.File, groups *importGroups, imports map[string]*importMeta) {
	var ranges []importRange

	for _, decl := range pf.Decls {
		dd, ok := decl.(*ast.GenDecl)
		if !ok || dd.Tok != token.IMPORT || isCgoDecl(dd) {
			continue
		}

		ranges = append(ranges, importRange{start: dd.Pos(), end: dd.End()})
		dd.Specs = f.rebuildImports(groups, imports)
	}

	clearImportComments(pf, ranges)
	removeEmptyImportDecls(pf)
}

func (f *SourceFile) rebuildImports(groups *importGroups, imports map[string]*importMeta) []ast.Spec {
	ordered := make([][]string, 0, len(f.importsOrders))
	for _, o := range f.importsOrders {
		switch o {
		case StdImportsOrder:
			ordered = append(ordered, groups.std)
		case GeneralImportsOrder:
			ordered = append(ordered, groups.general)
		case CompanyImportsOrder:
			ordered = append(ordered, groups.company)
		case ProjectImportsOrder:
			ordered = append(ordered, groups.project)
		case BlankedImportsOrder:
			ordered = append(ordered, groups.blanked)
		case DottedImportsOrder:
			ordered = append(ordered, groups.dotted)
		}
	}

	var specs []ast.Spec
	for _, group := range ordered {
		if len(group) == 0 {
			continue
		}
		if len(specs) > 0 {
			specs = append(specs, blankSpec())
		}

		if f.shouldSeparateNamedImports {
			var named, unnamed []string
			for _, imprt := range group {
				if name, _ := splitImport(imprt); name != "" {
					named = append(named, imprt)
				} else {
					unnamed = append(unnamed, imprt)
				}
			}
			for _, imprt := range unnamed {
				specs = append(specs, importSpec(imprt, imports))
			}
			if len(unnamed) > 0 && len(named) > 0 {
				specs = append(specs, blankSpec())
			}
			for _, imprt := range named {
				specs = append(specs, importSpec(imprt, imports))
			}
			continue
		}

		for _, imprt := range group {
			specs = append(specs, importSpec(imprt, imports))
		}
	}

	return specs
}

func blankSpec() ast.Spec {
	return &ast.ImportSpec{Path: &ast.BasicLit{Kind: token.STRING, Value: ""}}
}

func importSpec(imprt string, imports map[string]*importMeta) ast.Spec {
	value := imprt
	if meta, ok := imports[imprt]; ok && meta != nil && meta.comment != nil && len(meta.comment.List) > 0 {
		texts := make([]string, 0, len(meta.comment.List))
		for _, c := range meta.comment.List {
			texts = append(texts, c.Text)
		}
		value = imprt + " " + strings.Join(texts, " ")
	}

	return &ast.ImportSpec{Path: &ast.BasicLit{Kind: token.STRING, Value: value}}
}

// clearImportComments drops the comments which are located inside of the
// import declarations.
func clearImportComments(pf *ast.File, ranges []importRange) {
	if len(pf.Imports) == 0 {
		return
	}

	kept := make([]*ast.CommentGroup, 0, len(pf.Comments))
	for _, comment := range pf.Comments {
		inRange := false
		for _, r := range ranges {
			if r.contains(comment.Pos()) {
				inRange = true
				break
			}
		}
		if !inRange {
			kept = append(kept, comment)
		}
	}

	pf.Comments = kept
}

func removeEmptyImportDecls(pf *ast.File) {
	decls := make([]ast.Decl, 0, len(pf.Decls))
	for _, decl := range pf.Decls {
		if dd, ok := decl.(*ast.GenDecl); ok && dd.Tok == token.IMPORT && len(dd.Specs) == 0 {
			continue
		}
		decls = append(decls, decl)
	}
	pf.Decls = decls
}

// formatDecls forces a blank line between the top-level declarations.
func formatDecls(pf *ast.File) {
	for _, decl := range pf.Decls {
		switch dd := decl.(type) {
		case *ast.GenDecl:
			if dd.Doc == nil {
				dd.Doc = &ast.CommentGroup{}
			}
		case *ast.FuncDecl:
			if dd.Doc == nil {
				dd.Doc = &ast.CommentGroup{}
			}
		}
	}
}
EOF
echo ok"}

