package reviser

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

const recursivePath = "./..."

// SourceDir is a directory with Go source files which should be revised.
type SourceDir struct {
	projectName     string
	dir             string
	isRecursive     bool
	excludePatterns []string
}

// NewSourceDir creates a new SourceDir. The path "./..." is processed recursively.
func NewSourceDir(projectName, path string, isRecursive bool, excludes string) *SourceDir {
	if path == recursivePath {
		isRecursive = true
	}

	absPath, err := filepath.Abs(path)
	if err != nil {
		absPath = path
	}

	d := &SourceDir{
		projectName: projectName,
		dir:         absPath,
		isRecursive: isRecursive,
	}

	for _, pattern := range splitAndTrim(excludes) {
		if pattern == "" {
			continue
		}
		if !filepath.IsAbs(pattern) {
			pattern = filepath.Join(absPath, pattern)
		}
		d.excludePatterns = append(d.excludePatterns, pattern)
	}

	return d
}

// Fix revises all Go files of the directory and writes the result back.
func (d *SourceDir) Fix(options ...SourceFileOption) error {
	err := d.walk(func(path string) error {
		content, _, err := NewSourceFile(d.projectName, path).Fix(options...)
		if err != nil {
			return fmt.Errorf("failed to fix %s: %w", path, err)
		}
		if err := os.WriteFile(path, content, 0o644); err != nil {
			return fmt.Errorf("failed to write %s: %w", path, err)
		}
		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to walk dif: %w", err)
	}
	return nil
}

// Find returns the paths of the Go files whose formatting differs.
func (d *SourceDir) Find(options ...SourceFileOption) ([]string, error) {
	var files []string
	err := d.walk(func(path string) error {
		_, hasChange, err := NewSourceFile(d.projectName, path).Fix(options...)
		if err != nil {
			return fmt.Errorf("failed to fix %s: %w", path, err)
		}
		if hasChange {
			files = append(files, path)
		}
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to walk dif: %w", err)
	}
	return files, nil
}

func (d *SourceDir) walk(fn func(path string) error) error {
	return filepath.Walk(d.dir, func(path string, info fs.FileInfo, err error) error {
		if err != nil {
			return err
		}

		if info.IsDir() {
			if d.isExcluded(path) {
				return filepath.SkipDir
			}
			if path != d.dir && !d.isRecursive {
				return filepath.SkipDir
			}
			return nil
		}

		if !strings.HasSuffix(info.Name(), ".go") {
			return nil
		}
		if d.isExcluded(path) {
			return nil
		}

		return fn(path)
	})
}

func (d *SourceDir) isExcluded(path string) bool {
	for _, pattern := range d.excludePatterns {
		if matched, err := filepath.Match(pattern, path); err == nil && matched {
			return true
		}
	}
	return false
}
EOF
cat > reviser/project.go <<'EOF'
package reviser

import (
	"errors"
	"os"
	"path/filepath"

	"golang.org/x/mod/modfile"
)

const goModFileName = "go.mod"

// DetermineProjectName returns the explicitly passed project name or the
// module path of the nearest go.mod file. The lookup starts at startDir and
// goes up through the parents; the go.mod of the current directory is used
// as a fallback.
func DetermineProjectName(projectName, startDir string) (string, error) {
	if projectName != "" {
		return projectName, nil
	}

	dir := startDir
	for {
		goModPath := filepath.Join(dir, goModFileName)
		if _, err := os.Stat(goModPath); err == nil {
			return moduleName(goModPath)
		}

		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}

	return moduleName(goModFileName)
}

func moduleName(goModPath string) (string, error) {
	content, err := os.ReadFile(goModPath)
	if err != nil {
		return "", err
	}

	f, err := modfile.Parse(goModPath, content, nil)
	if err != nil {
		return "", err
	}

	if f.Module == nil || f.Module.Mod.Path == "" {
		return "", errors.New("module is undefined")
	}

	return f.Module.Mod.Path, nil
}
