func processDir(path string, options []reviser.SourceFileOption) bool {
	start := path
	if path == "./..." {
		start = "."
	}

	name, err := reviser.DetermineProjectName(projectName, start)
	if err != nil {
		printUsage()
		log.Fatalf("Could not determine project name for path %s: %s", path, err)
	}

	dir := reviser.NewSourceDir(name, path, isRecursive, excludes)

	if shouldListDiff {
		files, err := dir.Find(options...)
		if err != nil {
			log.Fatalf("Failed to find unformatted files %s: %+v", path, err)
		}
		for _, f := range files {
			fmt.Println(f)
		}
		return len(files) > 0
	}

	if err := dir.Fix(options...); err != nil {
		log.Fatalf("Failed to fix directory %s: %+v", path, err)
	}
	return false
}

// processFile revises a single file and reports whether it differs.
func processFile(path string, cache *fileCache, options []reviser.SourceFileOption) bool {
	name, err := reviser.DetermineProjectName(projectName, filepath.Dir(path))
	if err != nil {
		printUsage()
		log.Fatalf("Could not determine project name for path %s: %s", path, err)
	}

	absPath, err := filepath.Abs(path)
	if err != nil {
		log.Fatalf("Failed to fix file: %s", err)
	}

	if cache != nil {
		content, err := os.ReadFile(absPath)
		if err != nil {
			log.Fatalf("Failed to fix file: %s", err)
		}
		if cache.isFresh(absPath, content) {
			return false
		}
	}

	formatted, hasChange, err := reviser.NewSourceFile(name, absPath).Fix(options...)
	if err != nil {
		log.Fatalf("Failed to fix file: %s", err)
	}

	if cache != nil {
		if err := cache.store(absPath, formatted); err != nil {
			log.Fatalf("%s", err)
		}
	}

	if shouldListDiff {
		fmt.Println(absPath)
	}

	switch output {
	case outputStdout:
		if !shouldListDiff {
			fmt.Print(string(formatted))
		}
	case outputFile:
		if !shouldListDiff {
			if err := os.WriteFile(absPath, formatted, 0o644); err != nil {
				log.Fatalf("failed to write fixed result to file(%s): %+v", absPath, err)
			}
		}
	case outputWrite:
		if err := os.WriteFile(absPath, formatted, 0o644); err != nil {
			log.Fatalf("failed to write fixed result to file(%s): %+v", absPath, err)
		}
	default:
		log.Fatalf(`invalid output "%s" specified`, output)
	}

	return hasChange
}
