# Builds ./executable from the sources in this directory.
set -euo pipefail

cd "$(dirname "$0")"

export CGO_ENABLED=0
export GOFLAGS="${GOFLAGS:--mod=mod}"

GO_BIN="go"
MODCACHE="$(go env GOMODCACHE 2>/dev/null || true)"
LOCAL_TOOLCHAIN="${MODCACHE}/golang.org/toolchain@v0.0.1-go1.25.11.linux-amd64/bin/go"
if [ -x "${LOCAL_TOOLCHAIN}" ]; then
	# use the toolchain available in the module cache without any downloads
	GO_BIN="${LOCAL_TOOLCHAIN}"
	export GOTOOLCHAIN=local
fi

"${GO_BIN}" build -trimpath -o executable .
EOF
chmod +x compile.sh; cat > .gitignore <<'EOF'
/executable
*.test
*.out
EOF
GOPROXY=off ./compile.sh && ls -la executable && ./executable -version"}

