func TestFixGroupsAndSorts(t *testing.T) {
	src := `package main

import (
	"log"

	"github.com/example/myproj/pkg"

	"bytes"

	"golang.org/x/exp/slices"
	"fmt" // comment fmt
	_ "github.com/pkg1"
	. "github.com/pkg2"
)

func main() {
	fmt.Println(bytes.NewBuffer(nil), log.Flags(), slices.Contains, pkg.F)
}
`
	want := `package main

import (
	"bytes"
	"fmt" // comment fmt
	"log"

	_ "github.com/pkg1"
	. "github.com/pkg2"
	"golang.org/x/exp/slices"

	"github.com/example/myproj/pkg"
)

func main() {
	fmt.Println(bytes.NewBuffer(nil), log.Flags(), slices.Contains, pkg.F)
}
`
	got, changed := fixSource(t, src)
	if got != want {
		t.Errorf("unexpected result:\n%s", got)
	}
	if !changed {
		t.Error("expected the content to be changed")
	}
}

