func TestStringToImportsOrders(t *testing.T) {
	if _, err := StringToImportsOrders("std,foo"); err == nil || err.Error() != `unknown order group type: "foo"` {
		t.Errorf("unexpected error: %v", err)
	}
	if _, err := StringToImportsOrders("std,general"); err == nil {
		t.Error("expected an error for incomplete order")
	}
	orders, err := StringToImportsOrders(" ")
	if err != nil || len(orders) != 4 {
		t.Errorf("unexpected default orders: %v, %v", orders, err)
	}
	orders, err = StringToImportsOrders("project, company,general,std,blanked")
	if err != nil || len(orders) != 5 || orders[0] != ProjectImportsOrder {
		t.Errorf("unexpected orders: %v, %v", orders, err)
	}
}
